/* 状态模拟：:hover / :focus-visible 无法静态触发，下面三条是 PlanModeControl.module.css 中对应规则的原样副本。 */
.chip.forceHover { background: color-mix(in srgb, var(--dsw-alias-state-business-tertiary), var(--dsw-alias-state-business-primary) 6%); }
.chip.forceHover .restGlyph { display: none; }
.chip.forceHover .hoverGlyph { display: block; }
